---
import AreaChart from '@paulperigault/astro/AreaChart.astro';
import type { Dataset } from '@paulperigault/dataviz';

const sources: Dataset = {
  schema: 1,
  x: { kind: 'time', label: 'Mois', values: ['2025-01-01', '2025-02-01', '2025-03-01'] },
  series: [
    { id: 'recherche', label: 'Recherche', unit: 'visites', values: [410, 400, 450] },
    { id: 'direct', label: 'Direct', unit: 'visites', values: [260, 250, 270] },
  ],
};
---

<AreaChart id="visites-source" title="Visites par source" dataset={sources} />

---
import ArtDirection from '@paulperigault/astro/ArtDirection.astro';
import large from './large.jpg';
import largeEtroit from './large-etroit.jpg';
---

<ArtDirection
  src={large}
  sources={[{ at: 'narrow', src: largeEtroit }]}
  alt="Disque bleu et colonne grise"
/>

---
import BarChart from '@paulperigault/astro/BarChart.astro';
import type { Dataset } from '@paulperigault/dataviz';

const visites: Dataset = {
  schema: 1,
  x: { kind: 'category', label: 'Rubrique', values: ['Accueil', 'Guides', 'Journal'] },
  series: [{ id: 'visites', label: 'Visites', unit: 'visites', values: [3400, 2600, 700] }],
};
---

<BarChart id="visites-rubrique" title="Visites par rubrique" dataset={visites} orientation="horizontal" showValues />

---
import Diff from '@paulperigault/astro/Diff.astro';

const lines: { kind: 'add' | 'del' | 'ctx'; text: string }[] = [
  { kind: 'del', text: '  return items.length;' },
  { kind: 'add', text: '  return items.reduce((sum, item) => sum + item.price, 0);' },
];
---

<Diff
  caption="Calcul du total d’un panier"
  lines={lines}
  addedLabel="Ligne ajoutée"
  removedLabel="Ligne supprimée"
/>

---
import KpiCard from '@paulperigault/astro/KpiCard.astro';
---

<KpiCard
  id="visites-mois"
  title="Visites du mois"
  value={1190}
  unit="visites"
  reference={1240}
  referenceLabel="par rapport au mois précédent"
  trend={{ title: 'Visites par mois en 2025', dataset: visites }}
/>

---
import LineChart from '@paulperigault/astro/LineChart.astro';
import type { Dataset } from '@paulperigault/dataviz';

const visites: Dataset = {
  schema: 1,
  x: { kind: 'time', label: 'Mois', values: ['2025-01-01', '2025-02-01', '2025-03-01'] },
  series: [{ id: 'visites', label: 'Visites', unit: 'visites', values: [820, 790, null] }],
};
---

<LineChart id="visites-mensuelles" title="Visites mensuelles en 2025" dataset={visites} />

---
import Photo from '@paulperigault/astro/Photo.astro';
import portrait from './portrait.jpg';
---

<Photo src={portrait} alt="Portrait recadré, visage au centre" ratio="portrait" focal="top" />

---
const columns = [
  { key: 'name', label: 'Jeton' },
  { key: 'size', label: 'Valeur (rem)', numeric: true },
];
const rows = [{ name: '--pp-space-s', size: '1' }];
---
<Table caption="Jetons d’espacement" columns={columns} rows={rows} rowHeader="name" />

---
import Toast from '@paulperigault/astro/Toast.astro';
---
<Toast label="Notifications" dismissLabel="Fermer" />

<script>
  import { show } from './behaviors/toast';

  const region = document.querySelector('.pp-toast-region');
  if (region) show(region, { message: 'Réussi : brouillon enregistré.', tone: 'success' });
</script>
